import pandas as pd

def prepare_data(df):
    # Filter the dataset to include only rows with 'activity_label' as either stationary or active locomotion activities
    stationary_activities = ['sitting', 'standing']
    active_locomotion_activities = ['walking', 'jogging']
    filtered_df = df[(df['activity_label'].isin(stationary_activities)) | (df['activity_label'].isin(active_locomotion_activities))]

    # Sort the dataset by 'subject_id' and 'timestamp' to ensure chronological order
    sorted_df = filtered_df.sort_values(by=['subject_id', 'timestamp'])

    # Use a dictionary to store the filtered data, with 'subject_id' as the key
    data_dict = {}
    for index, row in sorted_df.iterrows():
        if row['subject_id'] not in data_dict:
            data_dict[row['subject_id']] = []
        data_dict[row['subject_id']].append(row)

    # Validation check: Verify that the filtered dataset contains at least one row for each 'subject_id' and that the 'timestamp' values are in ascending order
    for subject_id, rows in data_dict.items():
        if len(rows) < 1:
            raise ValueError(f"No rows found for subject_id {subject_id}")
        timestamps = [row['timestamp'] for row in rows]
        if timestamps != sorted(timestamps):
            raise ValueError(f"Timestamps are not in ascending order for subject_id {subject_id}")

    return data_dict

